/**
 * Review reproducer for candidate 2: a concurrent single-flight waiter of the same parameterized family must not
 * materialize the owner's value-dependent recipe (here: a predicate-range EmptySet proof valid only for the owner's
 * constant).
 */
class PackedPlanCacheFlightReviewReproTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("http://example.com/intValued");

	/** Provider proving PREDICATE holds only the canonical xsd:int value 7. */
	private static final PackedPredicateRangeProvider INT_SEVEN_PROVIDER = new PackedPredicateRangeProvider() {

		@Override
		public boolean describeObjectRange(IRI predicate, PackedPredicateRange output) {
			if (!PREDICATE.equals(predicate)) {
				return false;
			}
			output.setState(PackedPredicateRange.STATE_KNOWN);
			output.setKindBits(PackedPredicateRange.KIND_LITERAL);
			output.setLanguageBits(PackedPredicateRange.LANGUAGE_WITHOUT);
			output.addDatatype(CoreDatatype.XSD.INT);
			output.setUniversalBits(
					PackedPredicateRange.UNIVERSAL_NUMBER | PackedPredicateRange.UNIVERSAL_CANONICAL_INTEGER);
			output.setIntegerBounds(7L, 7L);
			output.setFinite(true);
			output.addFiniteValue(VF.createLiteral("7", CoreDatatype.XSD.INT));
			output.setDescription("RdfTermDomain[LITERAL, INT, integerRange=[7, 7]]");
			return true;
		}

		@Override
		public long predicateRangeVersion() {
			return 7L;
		}
	};

	@Test
	void constantObjectShapeFamilyAndBaselines() {
		report("object-9", objectQuery("9"));
		report("object-7", objectQuery("7"));
		report("filter-9", filterQuery("9"));
		report("filter-7", filterQuery("7"));
	}

	@Test
	void sequentialFamilyHitDoesNotReuseEmptyProofForInRangeConstant() {
		PackedPlanCache cache = new PackedPlanCache(32, 4);
		PackedPlanCache.Context context = context();
		GatedCostModel model = new GatedCostModel(null, null, null, new AtomicInteger());
		PackedPlanningResult outOfRange = plan(filterQuery("9"), cache, context, model);
		PackedPlanningResult inRange = plan(filterQuery("7"), cache, context, model);
		System.out.println("=== REVIEW-REPRO sequential out-of-range planCacheHit="
				+ outOfRange.metrics().planCacheHit() + "\n" + outOfRange.selectedPlan());
		System.out.println("=== REVIEW-REPRO sequential in-range planCacheHit=" + inRange.metrics().planCacheHit()
				+ "\n" + inRange.selectedPlan());
		assertTrue(containsNode(outOfRange.selectedPlan(), EmptySet.class), "precondition: 9 is proven empty");
		assertFalse(containsNode(inRange.selectedPlan(), EmptySet.class),
				"sequential family reuse must not apply the out-of-range EmptySet proof to 7");
	}

	@Test
	void concurrentFamilyWaiterMustNotMaterializeOwnersEmptyProof() throws Exception {
		assertFamilyWaiterNotEmpty(filterQuery("9"), filterQuery("7"), "filter");
	}

	@Test
	void concurrentFamilyWaiterMustNotMaterializeOwnersEmptyProofForConstantObject() throws Exception {
		assertFamilyWaiterNotEmpty(objectQuery("9"), objectQuery("7"), "object");
	}

	/**
	 * Candidate 3: a query template encoded with predicate-range facts is found by sameQueryContext, which ignores
	 * predicateRangeVersion, and re-used by planning that has no range provider (LMDB: dirty-transaction planning).
	 * Uses one segment to make the LMDB 16-segment collision (probability ~1/16) deterministic, and an anonymous
	 * projected variable so the query has no parameterized family (the template path is only taken then).
	 */
	@Test
	void queryTemplateWithRangeFactsMustNotServeProviderlessPlanning() {
		TupleExpr query = new Projection(new Filter(
				new StatementPattern(new Var("s", null, true, false), new Var("p", PREDICATE, true, true),
						new Var("o")),
				new Compare(new Var("o"), new ValueConstant(VF.createLiteral("9", CoreDatatype.XSD.INT)),
						Compare.CompareOp.EQ)),
				new ProjectionElemList(new ProjectionElem("s")));
		System.out.println("=== REVIEW-REPRO template family=" + PackedQueryFamilyIdentity.create(query, null));
		PackedPlanCache cache = new PackedPlanCache(32, 1);
		GatedCostModel model = new GatedCostModel(null, null, null, new AtomicInteger());
		PackedPlanCache.Context withRange = new PackedPlanCache.Context(1L, 0L, 0L, 4L, 5L, 6L, 11L, 7L);
		PackedPlanCache.Context withoutRange = new PackedPlanCache.Context(1L, 0L, 0L, 4L, 5L, 6L, 11L, 0L);

		TupleExpr providerlessBaseline = PackedCascadesPlanner
				.optimize(query.clone(), OptimizationGoal.root(query, null), model, null)
				.selectedPlan();
		TupleExpr ranged = PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(query, null), cache,
				withRange, model, INT_SEVEN_PROVIDER).selectedPlan();
		PackedPlanningResult providerless = PackedCascadesPlanner.optimize(query.clone(),
				OptimizationGoal.root(query, null), cache, withoutRange, model, null);
		System.out.println("=== REVIEW-REPRO template baseline:\n" + providerlessBaseline + "\nranged:\n" + ranged
				+ "\nproviderless planCacheHit=" + providerless.metrics().planCacheHit() + " templateHit="
				+ providerless.metrics().queryTemplateCacheHit() + "\n" + providerless.selectedPlan());

		assertFalse(containsNode(providerlessBaseline, EmptySet.class), "precondition: no provider, no proof");
		assertTrue(containsNode(ranged, EmptySet.class), "precondition: provider proves 9 empty");
		assertFalse(containsNode(providerless.selectedPlan(), EmptySet.class),
				"planning without a range provider must not inherit range facts from a cached query template");
	}

	private static void assertFamilyWaiterNotEmpty(TupleExpr ownerQuery, TupleExpr waiterQuery, String label)
			throws Exception {
		PackedQueryFamilyIdentity ownerFamily = PackedQueryFamilyIdentity.create(ownerQuery, INT_SEVEN_PROVIDER);
		PackedQueryFamilyIdentity waiterFamily = PackedQueryFamilyIdentity.create(waiterQuery, INT_SEVEN_PROVIDER);
		System.out.println("=== REVIEW-REPRO " + label + " familyMatches="
				+ (ownerFamily != null && ownerFamily.matches(waiterFamily))
				+ " concreteSameCacheIdentity=" + (ownerFamily != null && waiterFamily != null
						&& ownerFamily.concreteQuery().hasSameCacheIdentity(waiterFamily.concreteQuery())));

		PackedPlanCache cache = new PackedPlanCache(32, 4);
		PackedPlanCache.Context context = context();
		CountDownLatch ownerInSession = new CountDownLatch(1);
		CountDownLatch releaseOwner = new CountDownLatch(1);
		AtomicReference<Thread> ownerThread = new AtomicReference<>();
		AtomicInteger waiterSessions = new AtomicInteger();
		GatedCostModel model = new GatedCostModel(ownerThread, ownerInSession, releaseOwner, waiterSessions);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			Future<PackedPlanningResult> owner = executor.submit(() -> {
				ownerThread.set(Thread.currentThread());
				return plan(ownerQuery, cache, context, model);
			});
			assertTrue(ownerInSession.await(30, TimeUnit.SECONDS), "owner never opened its cost session");
			AtomicReference<Thread> waiterThread = new AtomicReference<>();
			Future<PackedPlanningResult> waiter = executor.submit(() -> {
				waiterThread.set(Thread.currentThread());
				return plan(waiterQuery, cache, context, model);
			});
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
			String observed = "timeout";
			while (System.nanoTime() < deadline) {
				Thread thread = waiterThread.get();
				if (waiterSessions.get() > 0) {
					observed = "waiter-planned-independently";
					break;
				}
				if (thread != null && thread.getState() == Thread.State.WAITING) {
					observed = "waiter-parked-on-owner-flight";
					break;
				}
				Thread.sleep(5L);
			}
			releaseOwner.countDown();
			PackedPlanningResult ownerResult = owner.get(30, TimeUnit.SECONDS);
			PackedPlanningResult waiterResult = waiter.get(30, TimeUnit.SECONDS);
			System.out.println("=== REVIEW-REPRO " + label + " interleaving=" + observed + " waiterSessions="
					+ waiterSessions.get() + " waiterPlanCacheHit=" + waiterResult.metrics().planCacheHit());
			System.out.println("owner plan:\n" + ownerResult.selectedPlan());
			System.out.println("waiter plan:\n" + waiterResult.selectedPlan());
			assertTrue(containsNode(ownerResult.selectedPlan(), EmptySet.class), "precondition: owner 9 is empty");
			assertFalse(containsNode(waiterResult.selectedPlan(), EmptySet.class),
					"waiter for in-range constant 7 materialized the owner's EmptySet proof (" + observed + ")");
		} finally {
			releaseOwner.countDown();
			executor.shutdownNow();
		}
	}

	private static void report(String label, TupleExpr query) {
		PackedPlanningResult result = plan(query, null, null, new GatedCostModel(null, null, null,
				new AtomicInteger()));
		System.out.println("=== REVIEW-REPRO baseline " + label + " empty="
				+ containsNode(result.selectedPlan(), EmptySet.class) + "\n" + result.selectedPlan());
	}

	private static PackedPlanningResult plan(TupleExpr query, PackedPlanCache cache, PackedPlanCache.Context context,
			PackedCostModel model) {
		TupleExpr source = query.clone();
		OptimizationGoal goal = OptimizationGoal.root(source, null);
		return cache == null
				? PackedCascadesPlanner.optimize(source, goal, model, INT_SEVEN_PROVIDER)
				: PackedCascadesPlanner.optimize(source, goal, cache, context, model, INT_SEVEN_PROVIDER);
	}

	private static PackedPlanCache.Context context() {
		return new PackedPlanCache.Context(1L, 0L, 0L, 4L, 5L, 6L, 11L, 7L);
	}

	private static TupleExpr filterQuery(String label) {
		return projection(new Filter(statementPattern(new Var("o")),
				new Compare(new Var("o"), new ValueConstant(VF.createLiteral(label, CoreDatatype.XSD.INT)),
						Compare.CompareOp.EQ)));
	}

	private static TupleExpr objectQuery(String label) {
		return projection(statementPattern(new Var("o_const", VF.createLiteral(label, CoreDatatype.XSD.INT), true,
				true)));
	}

	private static StatementPattern statementPattern(Var object) {
		return new StatementPattern(new Var("s"), new Var("p", PREDICATE, true, true), object);
	}

	private static Projection projection(TupleExpr arg) {
		return new Projection(arg, new ProjectionElemList(new ProjectionElem("s")));
	}

	private static boolean containsNode(TupleExpr root, Class<? extends QueryModelNode> type) {
		boolean[] found = new boolean[1];
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (type.isInstance(node)) {
					found[0] = true;
				}
				node.visitChildren(this);
			}
		});
		return found[0];
	}

	private static final class GatedCostModel implements PackedCostModel {

		private final AtomicReference<Thread> ownerThread;
		private final CountDownLatch ownerInSession;
		private final CountDownLatch releaseOwner;
		private final AtomicInteger otherSessions;

		private GatedCostModel(AtomicReference<Thread> ownerThread, CountDownLatch ownerInSession,
				CountDownLatch releaseOwner, AtomicInteger otherSessions) {
			this.ownerThread = ownerThread;
			this.ownerInSession = ownerInSession;
			this.releaseOwner = releaseOwner;
			this.otherSessions = otherSessions;
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query) {
			if (ownerThread != null && Thread.currentThread() == ownerThread.get()) {
				ownerInSession.countDown();
				try {
					if (!releaseOwner.await(30, TimeUnit.SECONDS)) {
						throw new IllegalStateException("owner release timed out");
					}
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new IllegalStateException(interrupted);
				}
			} else {
				otherSessions.incrementAndGet();
			}
			return PackedCostModel.super.openSession(query);
		}

		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isStatementPattern(relationId) ? 10_000.0d : Double.NaN;
		}

		@Override
		public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
				PackedCostEstimate output) {
			double rows = estimateRows(query, relationId);
			if (!Double.isFinite(rows)) {
				return;
			}
			if (context.prefixRelationCount() != 0
					&& query.prefixBindsStatementComponent(context, relationId, 2)) {
				output.setContextualRows(context.prefixRows(), context.prefixRows());
			} else {
				output.setRows(rows, rows);
			}
		}
	}
}
